custom_css:
[data-pp-custom-block="greetings-time-slider"] {
  border: 1px solid #e2e8f0;
  background: #ffffff;
  border-radius: 16px;
  padding: 16px;
  max-width: 720px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 14px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-title {
  color: #0f172a;
  margin: 0;
  font-size: 18px;
  line-height: 1.25;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-subtitle {
  margin: 0;
  font-size: 14px;
  line-height: 1.35;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-timewrap {
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-time {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-time-label {
  color: #64748b;
  font-size: 14px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-time-value {
  color: #0f172a;
  font-weight: 700;
  font-size: 22px;
  letter-spacing: -0.01em;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-slider {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-slider-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-range {
  width: 100%;
  cursor: pointer;
  accent-color: #475dd7;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-range:focus {
  outline: 2px solid rgba(71, 93, 215, 0.35);
  outline-offset: 3px;
  border-radius: 10px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-range-hints {
  position: relative;
  height: 16px;
  color: #64748b;
  font-size: 12px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-hint {
  position: absolute;
  top: 0;
  transform: translateX(-50%);
  white-space: nowrap;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-hint.is-left {
  transform: translateX(0);
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-hint.is-right {
  transform: translateX(-100%);
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-hero {
  border: 1px solid rgba(71, 93, 215, 0.25);
  background: rgba(71, 93, 215, 0.06);
  border-radius: 14px;
  padding: 14px 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-align: center;
  transition: background 0.28s ease, border-color 0.28s ease, transform 0.28s ease;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-hero.is-pulse {
  transform: translateY(-1px);
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-emoji {
  font-size: 22px;
  line-height: 1;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-word {
  color: #0f172a;
  font-size: 22px;
  letter-spacing: -0.01em;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-tip {
  font-size: 13px;
  line-height: 1.35;
  margin-top: 2px;
}

[data-pp-custom-block="greetings-time-slider"] .pp-greet-tip.is-flash {
  color: #475dd7;
}

/* Wider screens: keep it airy but compact */
@media (min-width: 640px) {
  [data-pp-custom-block="greetings-time-slider"] {
    padding: 18px;
  }

  [data-pp-custom-block="greetings-time-slider"] .pp-greet-timewrap {
    padding: 16px;
    gap: 14px;
  }

  [data-pp-custom-block="greetings-time-slider"] .pp-greet-emoji {
    font-size: 24px;
  }

  [data-pp-custom-block="greetings-time-slider"] .pp-greet-word {
    font-size: 24px;
  }
}

custom_js:
(() => {
  const root = document.querySelector('[data-pp-custom-block="greetings-time-slider"]');
  if (!root) return;

  const range = root.querySelector('#pp-greet-time-range');
  const timeValueEl = root.querySelector('[data-time-value]');
  const hero = root.querySelector('.pp-greet-hero');
  const greetEmojiEl = root.querySelector('[data-greet-emoji]');
  const greetWordEl = root.querySelector('[data-greet-word]');
  const tipEl = root.querySelector('[data-boundary-tip]');
  const hintEls = Array.from(root.querySelectorAll('.pp-greet-hint'));

  if (!range || !timeValueEl || !hero || !greetEmojiEl || !greetWordEl || !tipEl) return;

  // Minutes since midnight -> "h:mm a.m./p.m."
  const toAmPm = (mins) => {
    let h24 = Math.floor(mins / 60);
    let m = mins % 60;

    const isPm = h24 >= 12;
    let h12 = h24 % 12;
    if (h12 === 0) h12 = 12;

    const mm = String(m).padStart(2, "0");
    const suffix = isPm ? "p.m." : "a.m.";
    return `${h12}:${mm} ${suffix}`;
  };

  // Boundaries:
  // - Buenos días: < 12:00 p.m. (mins < 720)
  // - Buenas tardes: 12:00 p.m. to < 8:00 p.m. (720 <= mins < 1200)
  // - Buenas noches: >= 8:00 p.m. (mins >= 1200)
  const getGreeting = (mins) => {
    if (mins < 720) return { key: "dias", word: "Buenos días", emoji: "☀️" };
    if (mins < 1200) return { key: "tardes", word: "Buenas tardes", emoji: "🌤️" };
    return { key: "noches", word: "Buenas noches", emoji: "🌙" };
  };

  const setHero = (g) => {
    greetEmojiEl.textContent = g.emoji;
    greetWordEl.innerHTML = `<strong>${g.word}</strong>`;
  };

  const pulseHero = () => {
    hero.classList.add("is-pulse");
    window.setTimeout(() => hero.classList.remove("is-pulse"), 260);
  };

  const flashTip = (text) => {
    tipEl.textContent = text;
    tipEl.classList.add("is-flash");
    window.setTimeout(() => tipEl.classList.remove("is-flash"), 650);
  };

  const crossesBoundary = (prevMins, nextMins, boundaryMins) => {
    if (prevMins == null) return false;
    return (
      (prevMins < boundaryMins && nextMins >= boundaryMins) ||
      (prevMins >= boundaryMins && nextMins < boundaryMins)
    );
  };

  const positionHints = () => {
    if (!hintEls.length) return;

    const min = parseInt(range.min, 10);
    const max = parseInt(range.max, 10);
    const span = Math.max(1, max - min);

    hintEls.forEach((el) => {
      const v = parseInt(el.getAttribute("data-mins"), 10);
      const pct = ((v - min) / span) * 100;

      el.style.left = `${pct}%`;

      el.classList.remove("is-left", "is-right");
      if (v <= min) el.classList.add("is-left");
      if (v >= max) el.classList.add("is-right");
    });
  };

  let prevMins = null;
  let prevGreetingKey = null;

  const updateFromSlider = () => {
    const mins = parseInt(range.value, 10);

    timeValueEl.textContent = toAmPm(mins);

    const g = getGreeting(mins);
    setHero(g);

    if (prevGreetingKey && prevGreetingKey !== g.key) {
      pulseHero();
    }

    if (crossesBoundary(prevMins, mins, 720)) {
      flashTip("At 12:00 p.m., the greeting switches: Buenos días → Buenas tardes.");
    } else if (crossesBoundary(prevMins, mins, 1200)) {
      flashTip("At 8:00 p.m., the greeting switches: Buenas tardes → Buenas noches.");
    }

    prevMins = mins;
    prevGreetingKey = g.key;
  };

  range.addEventListener("input", updateFromSlider);
  range.addEventListener("change", updateFromSlider);
  window.addEventListener("resize", positionHints);

  // Initialize
  positionHints();
  updateFromSlider();
})();
